tool_input.command:
echo "=== jaeger traces for recommendation ==="
curl -s 'http://localhost:16686/jaeger/ui/api/traces?service=recommendation&lookback=1h&limit=5' | python3 -c "
import json,sys
d=json.load(sys.stdin)
for t in d.get('data',[]):
    spans=t['spans']
    for s in spans:
        if s.get('operationName'):
            tags={x['key']:x['value'] for x in s.get('tags',[])}
            if tags.get('error') or tags.get('otel.status_code')=='ERROR':
                print(t['traceID'], s['operationName'], tags.get('error'), s.get('duration'))
"
